+    if (e.status !== 'active') continue;
+    (byKind.get(e.kind) ?? byKind.get('prompt')).push(e);
+  }
+  for (const list of byKind.values()) {
+    list.sort((a, b) => String(b.updatedAt ?? '').localeCompare(String(a.updatedAt ?? '')));
+  }
