+  const lines = [];
+  let used = header.length;
+  let shown = 0;
+  for (const entry of active) {
+    const line = `\n- [${entry.kind}] ${entry.title}: ${entry.content}`;
+    const willOmit = shown + 1 < active.length;
+    if (used + line.length + (willOmit ? reserve : 0) > cap) break;
+    lines.push(line);
+    used += line.length;
+    shown += 1;
+  }
